package com.shopsphere.dao;
import com.shopsphere.config.DBConnection;import java.sql.*;import java.util.*;
public class AdminAnalyticsDAO{public Map<String,Object> summary()throws SQLException{Map<String,Object> m=new LinkedHashMap<>();String q="SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM products WHERE status=TRUE) products,(SELECT COUNT(*) FROM orders) orders,(SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE order_status<>'CANCELLED') revenue,(SELECT COUNT(*) FROM reviews) reviews";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){if(r.next()){m.put("users",r.getInt(1));m.put("products",r.getInt(2));m.put("orders",r.getInt(3));m.put("revenue",r.getBigDecimal(4));m.put("reviews",r.getInt(5));}}return m;}public List<Map<String,Object>> recentOrders()throws SQLException{List<Map<String,Object>> out=new ArrayList<>();String q="SELECT DATE(created_at),COUNT(*),COALESCE(SUM(total_amount),0) FROM orders WHERE order_status<>'CANCELLED' GROUP BY DATE(created_at) ORDER BY DATE(created_at) DESC LIMIT 7";try(Connection c=DBConnection.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){while(r.next()){Map<String,Object> m=new LinkedHashMap<>();m.put("day",r.getDate(1));m.put("orders",r.getInt(2));m.put("revenue",r.getBigDecimal(3));out.add(m);}}return out;}}
